API_name: get_financial_data
Description:
{
  "description": "Customizable Endpoint for various financial data functions.",
  "required_parameters": [
    {
      "name": "function",
      "type": "String",
      "description": "The function of your choice (This is required for all API calls). For this example, the value is GLOBAL_QUOTE.",
      "default": "GLOBAL_QUOTE"
    },
    {
      "name": "symbol",
      "type": "String",
      "description": "Any additional optional parameters may be added. Some functions have multiple required parameters, check the documentation for more information.",
      "default": "TSLA"
    }
  ],
  "optional_parameters": []
}

